# Builds src/brand/splashScript.ts: the wordmark "Delegent AI" as SVG paths, so
# the splash can write "Delegent" out by hand (each letter's outline traced like
# a pen, then inked in) and set "AI" beside it. Same fonts and proportions as
# Wordmark size "lg" (Instrument Serif Italic 44 with -0.4 tracking; Geist
# Medium 22 with 1.4 tracking; a 10 px gap), sitting on one baseline.
#
#   python apps/mobile/scripts/build-splash-script.py
#
# Needs fontTools (pip install fonttools). The fonts come from node_modules, so
# run it after npm install. Commit the generated file; the app never runs this.
import io
import os

from fontTools.pens.perimeterPen import PerimeterPen
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen
from fontTools.ttLib import TTFont

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', '..'))
FONTS = os.path.join(ROOT, 'node_modules', '@expo-google-fonts')
SERIF = os.path.join(FONTS, 'instrument-serif', '400Regular_Italic', 'InstrumentSerif_400Regular_Italic.ttf')
SANS = os.path.join(FONTS, 'geist', '500Medium', 'Geist_500Medium.ttf')
OUT = os.path.join(ROOT, 'apps', 'mobile', 'src', 'brand', 'splashScript.ts')


def run(font_path, text, size, tracking, start_x, baseline):
    font = TTFont(font_path)
    glyph_set = font.getGlyphSet()
    cmap = font.getBestCmap()
    upm = font['head'].unitsPerEm
    scale = size / upm
    x = start_x
    glyphs = []
    for char in text:
        name = cmap[ord(char)]
        glyph = glyph_set[name]
        # Font units point up; SVG units point down.
        transform = (scale, 0, 0, -scale, x, baseline)
        svg = SVGPathPen(glyph_set, ntos=lambda v: f'{v:.2f}'.rstrip('0').rstrip('.'))
        glyph.draw(TransformPen(svg, transform))
        perimeter = PerimeterPen(glyph_set)
        glyph.draw(perimeter)
        glyphs.append({'char': char, 'd': svg.getCommands(), 'length': round(perimeter.value * scale, 1)})
        x += glyph.width * scale + tracking
    return glyphs, x - tracking, font, scale


def main():
    serif = TTFont(SERIF)
    serif_scale = 44 / serif['head'].unitsPerEm
    ascent = serif['hhea'].ascent * serif_scale
    descent = -serif['hhea'].descent * serif_scale
    pad = 4
    baseline = pad + ascent
    script, script_end, _, _ = run(SERIF, 'Delegent', 44, -0.4, pad, baseline)
    sans, sans_end, _, _ = run(SANS, 'AI', 22, 1.4, script_end + 10, baseline)
    width = sans_end + pad
    height = baseline + descent + pad
    lines = [
        '// GENERATED by apps/mobile/scripts/build-splash-script.py. Do not edit by hand.',
        '// "Delegent" in Instrument Serif Italic and "AI" in Geist Medium, laid out',
        '// like Wordmark size "lg", as SVG paths the splash can write out by hand.',
        '',
        f'export const SPLASH_SCRIPT_VIEWBOX = {{ width: {width:.1f}, height: {height:.1f} }} as const;',
        '',
        '/** One path per letter of "Delegent", with its outline length for the pen. */',
        'export const SPLASH_SCRIPT_LETTERS: ReadonlyArray<{ char: string; d: string; length: number }> = [',
    ]
    for g in script:
        lines.append(f"  {{ char: '{g['char']}', length: {g['length']}, d: '{g['d']}' }},")
    lines += ['];', '', '/** "AI", set after the script is written. */',
              'export const SPLASH_SANS_LETTERS: ReadonlyArray<{ char: string; d: string }> = [']
    for g in sans:
        lines.append(f"  {{ char: '{g['char']}', d: '{g['d']}' }},")
    lines += ['];', '']
    io.open(OUT, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines))
    print(f'wrote {OUT}: {len(script)} script letters, {len(sans)} sans letters, viewBox {width:.1f} x {height:.1f}')
    for g in script:
        print(f"  {g['char']} length {g['length']}")


if __name__ == '__main__':
    main()
